(679461, 70810, 18197, '<td valign="top">Not sure about the relevance to theme but I am sure this is a beautiful photo. Good luck in the scoring.</td>', 'Not sure about the relevance to theme but I am sure this is a beautiful photo. Good luck in the scoring.', '2004-04-21 12:47:46.000000', NULL, 1),
(679462, 70645, 18197, '<td valign="top">Imaginitive idea. Well executed.</td>', 'Imaginitive idea. Well executed.', '2004-04-21 12:48:23.000000', NULL, 1),
(679471, 71300, 14601, '<td valign="top">Hmmm. The only way this could really be serendipity is that the owner of the pennies wanted to trade them in for bills or larger denomination coins, and chose an extraordinarily honest numismatist as the ''banker''. Hopefully others will "get" what this particular coin represents. And, hopefully the coin is YOURS. Photographically, I applaud everything about the shot -l focus, color, crop, and composition. A 10 from me.</td>', 'Hmmm. The only way this could really be serendipity is that the owner of the pennies wanted to trade them in for bills or larger denomination coins, and chose an extraordinarily honest numismatist as the ''banker''. Hopefully others will "get" what this particular coin represents. And, hopefully the coin is YOURS. Photographically, I applaud everything about the shot -l focus, color, crop, and composition. A 10 from me.', '2004-04-21 12:53:16.000000', NULL, 1),
(679473, 71305, 18197, '<td valign="top">I suppose there will be a tutorial explaining how you did it within basic editing rules. It is an exceptional image but I am unsure it is an exceptional photo. Color is great. Composition is good. Interesting relevance to theme.</td>', 'I suppose there will be a tutorial explaining how you did it within basic editing rules. It is an exceptional image but I am unsure it is an exceptional photo. Color is great. Composition is good. Interesting relevance to theme.', '2004-04-21 12:54:37.000000', NULL, 1),
(679477, 71305, 7907, '<td valign="top">This is just so creative and beautifully executed! 10</td>', 'This is just so creative and beautifully executed! 10', '2004-04-21 12:56:54.000000', NULL, 1),
(679478, 71318, 18197, '<td valign="top">I can appreciate you took a risk with this photo. It is well executed: Levels, contrast, composition ... But I fear many will consider it in poor taste.</td>', 'I can appreciate you took a risk with this photo. It is well executed: Levels, contrast, composition ... But I fear many will consider it in poor taste.', '2004-04-21 12:57:26.000000', NULL, 1),
(679480, 71083, 19670, '<td valign="top">Maybe it''s hope (cool juxtaposition of the sign) , but it seems a stretch to be serendipity--nothing is shown to be "found."</td>', 'Maybe it''s hope (cool juxtaposition of the sign) , but it seems a stretch to be serendipity--nothing is shown to be "found."', '2004-04-21 12:58:03.000000', NULL, 1),
(679487, 70722, 20168, '<td valign="top">A true serendipity! An unexpected invitation to sit and soak in the beauty from one of the most incredible places on earth!  Congrats on a great photo.  Less grass and more ocean would have made this photo even more wonderful.</td>', 'A true serendipity! An unexpected invitation to sit and soak in the beauty from one of the most incredible places on earth!  Congrats on a great photo.  Less grass and more ocean would have made this photo even more wonderful.', '2004-04-21 13:03:27.000000', NULL, 1),
