INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(680556, 71083, 18349, '<td valign="top">Very original idea.  Love it.</td>', 'Very original idea.  Love it.', '2004-04-21 23:25:43.000000', NULL, 1),
(680560, 70521, 18349, '<td valign="top">I can hear them now...."Mine...Mine...Mine..."</td>', 'I can hear them now...."Mine...Mine...Mine..."', '2004-04-21 23:27:08.000000', NULL, 1),
(680564, 70507, 18552, '<td valign="top">What a fun serendipitous find.</td>', 'What a fun serendipitous find.', '2004-04-21 23:30:32.000000', NULL, 1),
(680611, 71308, 18868, '<td valign="top">Very nice!  I''m thinking top 20.</td>', 'Very nice!  I''m thinking top 20.', '2004-04-21 23:53:51.000000', NULL, 1),
(680619, 71149, 18868, '<td valign="top">Cool pic -- I wish that the sun hadn''t blown out the highlights, altho I don''t know how to accomplish it.</td>', 'Cool pic -- I wish that the sun hadn''t blown out the highlights, altho I don''t know how to accomplish it.', '2004-04-22 00:01:13.000000', NULL, 1),
(680650, 70764, 14202, '<td valign="top">Love the concept, the very bright area on the case lid is a quite distracting.  But good none the less.</td>', 'Love the concept, the very bright area on the case lid is a quite distracting.  But good none the less.', '2004-04-22 00:29:59.000000', NULL, 1),
(680652, 70323, 13077, '<td valign="top">Nice compositition, and if the goal was to capture a shot using luck, it appears you did so well.</td>', 'Nice compositition, and if the goal was to capture a shot using luck, it appears you did so well.', '2004-04-22 00:31:12.000000', NULL, 1),
(680653, 71236, 14202, '<td valign="top">the car is sooooo lost in all the shadows.</td>', 'the car is sooooo lost in all the shadows.', '2004-04-22 00:31:23.000000', NULL, 1),
(680656, 70837, 13077, '<td valign="top">The angle, and the objects in the picture seem very confusing...</td>', 'The angle, and the objects in the picture seem very confusing...', '2004-04-22 00:32:42.000000', NULL, 1),
(680657, 70494, 13077, '<td valign="top">I hope you didn''t eat them out of the underwear... :/</td>', 'I hope you didn''t eat them out of the underwear... :/', '2004-04-22 00:33:34.000000', NULL, 1),
(680658, 71313, 13077, '<td valign="top">I like the border and tones, and I can understand by the title how it meets the challenge. Nice picture, but a little wider DOF would have been nicer.<br/></td>', 'I like the border and tones, and I can understand by the title how it meets the challenge. Nice picture, but a little wider DOF would have been nicer.', '2004-04-22 00:34:48.000000', NULL, 1),
(680663, 70863, 18868, '<td valign="top">It''s a reasonably nice composition, but it''s under exposed and flat.  Also, it seems that your white balance could be adjusted (when shooting the original rather than in photoshop, which would cause the metallic highlights to blow out) so the white of the paper is fully white.  I would share the opinion that having numerous items in the frame calls for a longer DOF.  Good effort.</td>', 'It''s a reasonably nice composition, but it''s under exposed and flat.  Also, it seems that your white balance could be adjusted (when shooting the original rather than in photoshop, which would cause the metallic highlights to blow out) so the white of the paper is fully white.  I would share the opinion that having numerous items in the frame calls for a longer DOF.  Good effort.', '2004-04-22 00:39:05.000000', NULL, 1),
(680667, 71241, 18868, '<td valign="top">Nice image, I wish it were a little sharper, perhaps a little less blown out in the sun.</td>', 'Nice image, I wish it were a little sharper, perhaps a little less blown out in the sun.', '2004-04-22 00:44:17.000000', NULL, 1),
(680669, 70952, 20395, '<td valign="top">Like the angle. Wish the subject, not the background, was in focus. Definetely a good choice with the b&amp;w!</td>', 'Like the angle. Wish the subject, not the background, was in focus. Definetely a good choice with the b&w!', '2004-04-22 00:45:26.000000', NULL, 1),
(680670, 70816, 13077, '<td valign="top">Nice angles, I don''t know about it meeting the challenge, but... <br/></td>', 'Nice angles, I don''t know about it meeting the challenge, but... ', '2004-04-22 00:48:33.000000', NULL, 1),
(680671, 70438, 18868, '<td valign="top">Very cool -- this really truely captures my perception of the topic!  Nice image.  I was going to suggest techniques to make the rear stone sharper, but on reflection, it doesn''t really need it, and might compete too much with the foreground image.  Top 10 for sure!</td>', 'Very cool -- this really truely captures my perception of the topic!  Nice image.  I was going to suggest techniques to make the rear stone sharper, but on reflection, it doesn''t really need it, and might compete too much with the foreground image.  Top 10 for sure!', '2004-04-22 00:48:42.000000', NULL, 1),
(680694, 71107, 772, '<td valign="top">amazingly beautiful.  the rare treat of being in the rain as a child... it brings back memories.  = 10</td>', 'amazingly beautiful.  the rare treat of being in the rain as a child... it brings back memories.  = 10', '2004-04-22 01:19:32.000000', NULL, 1),
