(681972, 70718, 19780, '<td valign="top">An intriguing shot. The composition is good, but the exposure is a little too yellow/orange. The concept of hammering a screw is an odd interpretation of serendipity - I''m not sure it fits. I''d like to see the whole hammer head in the frame, or cropped more  at the top, as it is now, it feels a little off in balance.</td>', 'An intriguing shot. The composition is good, but the exposure is a little too yellow/orange. The concept of hammering a screw is an odd interpretation of serendipity - I''m not sure it fits. I''d like to see the whole hammer head in the frame, or cropped more  at the top, as it is now, it feels a little off in balance.', '2004-04-22 22:57:32.000000', NULL, 1),
(681973, 71300, 10082, '<td valign="top">Great photo.  I love the color and composition.  As a collector, I know what a nice suprise this would be :)</td>', 'Great photo.  I love the color and composition.  As a collector, I know what a nice suprise this would be :)', '2004-04-22 22:58:44.000000', NULL, 1),
(681975, 70474, 19780, '<td valign="top">A lovely photo - the colors are wonderfullly rich and the fuzziness of the bee is quite a treat. I''m not sure it fits the challenge - a bee finds nectar and flowers because that''s what they were born to do. But I can identify with the delight of watching one and how that can feel like a happy accident.</td>', 'A lovely photo - the colors are wonderfullly rich and the fuzziness of the bee is quite a treat. I''m not sure it fits the challenge - a bee finds nectar and flowers because that''s what they were born to do. But I can identify with the delight of watching one and how that can feel like a happy accident.', '2004-04-22 22:59:36.000000', NULL, 1),
(681979, 71074, 19780, '<td valign="top">What a delightful photo - the full frame of bear is quite a find. I wish I could actually see the apple - I wouldn''t know that''s what it was unless I saw the title. The composition is a little distant and the center of interest isn''t quite defined but I''m sure you didn''t want to get too close to frame it optimally!</td>', 'What a delightful photo - the full frame of bear is quite a find. I wish I could actually see the apple - I wouldn''t know that''s what it was unless I saw the title. The composition is a little distant and the center of interest isn''t quite defined but I''m sure you didn''t want to get too close to frame it optimally!', '2004-04-22 23:04:25.000000', NULL, 1),
(681982, 70574, 6532, '<td valign="top">This would have been much more appealling to me if the setting was cleaner and the head of the penny was right side up.  Good DOF.</td>', 'This would have been much more appealling to me if the setting was cleaner and the head of the penny was right side up.  Good DOF.', '2004-04-22 23:05:52.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(681985, 71282, 19780, '<td valign="top">Delightful sense of whimsy. I wish I could see the faces of the geese but the detail and shadow on the wings is quite nice as well. The candid catch of this feels like it meets the challenge of serendipity.</td>', 'Delightful sense of whimsy. I wish I could see the faces of the geese but the detail and shadow on the wings is quite nice as well. The candid catch of this feels like it meets the challenge of serendipity.', '2004-04-22 23:07:06.000000', NULL, 1),
(681986, 70628, 6532, '<td valign="top">Wonderful clarity.... Good composition.   Good job.</td>', 'Wonderful clarity.... Good composition.   Good job.', '2004-04-22 23:08:10.000000', NULL, 1),
(681989, 71155, 6532, '<td valign="top">Maybe if we were closer to the dandelion...the subject would be more distinguishable.</td>', 'Maybe if we were closer to the dandelion...the subject would be more distinguishable.', '2004-04-22 23:10:06.000000', NULL, 1),
(681991, 71208, 6532, '<td valign="top">Nice composition and use of red background.  Good job!</td>', 'Nice composition and use of red background.  Good job!', '2004-04-22 23:11:59.000000', NULL, 1),
(682006, 70449, 5792, '<td valign="top">Good idea... Some folk''s idea of serendipity differs from others.  :) Needs a little more contrast.</td>', 'Good idea... Some folk''s idea of serendipity differs from others.  :) Needs a little more contrast.', '2004-04-22 23:27:34.000000', NULL, 1),
(682012, 71261, 5792, '<td valign="top">Good concept but the ripples in this image lack depth and interest. Perhaps taking them at sunrise or sunset would add more to it and give it better contrast. Having a "unique" ripple (whatever that might mean) would also provide a focal point for the viewer.  This type of capture, though simple in concept, is difficult to pull off.</td>', 'Good concept but the ripples in this image lack depth and interest. Perhaps taking them at sunrise or sunset would add more to it and give it better contrast. Having a "unique" ripple (whatever that might mean) would also provide a focal point for the viewer.  This type of capture, though simple in concept, is difficult to pull off.', '2004-04-22 23:33:01.000000', NULL, 1),
(682030, 70897, 5792, '<td valign="top">Nice capture, good DOF and good quality. The digital halo on the rear end of the insect is its only fault.</td>', 'Nice capture, good DOF and good quality. The digital halo on the rear end of the insect is its only fault.', '2004-04-22 23:41:48.000000', NULL, 1),
(682035, 71205, 5792, '<td valign="top">Great concept but the agitator top being the brightest object in the frame and out of focus is a distraction that hurts this image. Greater depth of field is all it needs.</td>', 'Great concept but the agitator top being the brightest object in the frame and out of focus is a distraction that hurts this image. Greater depth of field is all it needs.', '2004-04-22 23:44:41.000000', NULL, 1),
(682044, 71232, 5792, '<td valign="top">This is a great concept. This image captures the essence of bartering at a flea market perfectly.  The border does not work for me since if guts off the white hair on the leftmost subject''s head. It could use a bit more contrast and the white blob on the far right should be cropped out.</td>', 'This is a great concept. This image captures the essence of bartering at a flea market perfectly.  The border does not work for me since if guts off the white hair on the leftmost subject''s head. It could use a bit more contrast and the white blob on the far right should be cropped out.', '2004-04-22 23:50:11.000000', NULL, 1),
(682051, 70321, 12151, '<td valign="top">The starbursts make this photo very interesting, although it seems to be too grainy given the details of the image.  Nice composition otherwise.</td>', 'The starbursts make this photo very interesting, although it seems to be too grainy given the details of the image.  Nice composition otherwise.', '2004-04-22 23:55:03.000000', NULL, 1),
(682052, 71034, 5792, '<td valign="top">A touch of color saturation and contrast would make this wonderful capture even better.</td>', 'A touch of color saturation and contrast would make this wonderful capture even better.', '2004-04-22 23:55:06.000000', NULL, 1),
(682054, 70696, 12151, '<td valign="top">Great photo - a more subtle sense of serendipity, although it does rely on your title a bit.  It''s still top-notch composition and should score high.</td>', 'Great photo - a more subtle sense of serendipity, although it does rely on your title a bit.  It''s still top-notch composition and should score high.', '2004-04-22 23:56:12.000000', NULL, 1),
(682058, 70943, 12151, '<td valign="top">This had better win - it easily is the best photo that conveys some strong semblance of "serendipity" without explaining itself in the title.  And it looks great, too - technically, and in terms of composition.  Hilarious face.  Top score for the week.</td>', 'This had better win - it easily is the best photo that conveys some strong semblance of "serendipity" without explaining itself in the title.  And it looks great, too - technically, and in terms of composition.  Hilarious face.  Top score for the week.', '2004-04-22 23:58:22.000000', NULL, 1),
(682061, 71107, 12151, '<td valign="top">This has a peaceful, more indirect, and more definite sense of serendipity than the other photos here.  It works very well.  Thanks for not putting a paragraph into your title to explain it!  It takes a little longer to sense it, but it makes you appreciate the photo tons more.</td>', 'This has a peaceful, more indirect, and more definite sense of serendipity than the other photos here.  It works very well.  Thanks for not putting a paragraph into your title to explain it!  It takes a little longer to sense it, but it makes you appreciate the photo tons more.', '2004-04-23 00:01:48.000000', NULL, 1),
(682092, 70997, 18505, '<td valign="top">What a beautiful picture!!  I''m sure someone will tell you they would prefer the cows to be a little to the left or to the right, but I like them right where you put them.  I can''t wait to find out where this is.  Good job!!</td>', 'What a beautiful picture!!  I''m sure someone will tell you they would prefer the cows to be a little to the left or to the right, but I like them right where you put them.  I can''t wait to find out where this is.  Good job!!', '2004-04-23 00:29:01.000000', NULL, 1),
(682093, 71203, 18505, '<td valign="top">Very nice!!  Reminds me how much I miss cardinals here.  Lovely image.</td>', 'Very nice!!  Reminds me how much I miss cardinals here.  Lovely image.', '2004-04-23 00:32:46.000000', NULL, 1),
(682098, 70459, 19794, '<td valign="top">awesome pic like the clover idea, funny title, nice contrast between the greens and whites</td>', 'awesome pic like the clover idea, funny title, nice contrast between the greens and whites', '2004-04-23 00:38:38.000000', NULL, 1),
(682099, 71211, 19794, '<td valign="top">pretty cool lookin</td>', 'pretty cool lookin', '2004-04-23 00:38:48.000000', NULL, 1),
(682100, 70943, 19794, '<td valign="top">kind of silly</td>', 'kind of silly', '2004-04-23 00:39:05.000000', NULL, 1),
