(682103, 70897, 18505, '<td valign="top">Beautiful image.  What kind of lens do you use?  I''m not real crazy about the yellow border, but am not counting down for that.  The picture is terrific by itself.  Good work!!</td>', 'Beautiful image.  What kind of lens do you use?  I''m not real crazy about the yellow border, but am not counting down for that.  The picture is terrific by itself.  Good work!!', '2004-04-23 00:41:44.000000', NULL, 1),
(682108, 71107, 6600, '<td valign="top">Can you say RIBBON WINNER?  Great job!<br/></td>', 'Can you say RIBBON WINNER?  Great job!', '2004-04-23 00:47:30.000000', NULL, 1),
(682109, 70807, 19794, '<td valign="top">gross, but funny, nice idea.</td>', 'gross, but funny, nice idea.', '2004-04-23 00:49:38.000000', NULL, 1),
(682115, 71113, 18505, '<td valign="top">Amazing!!  How lucky to witness and record the beginning of a new life.  I hope mother and baby are doing well.  Please let us know.  Good luck in the challenge.</td>', 'Amazing!!  How lucky to witness and record the beginning of a new life.  I hope mother and baby are doing well.  Please let us know.  Good luck in the challenge.', '2004-04-23 01:04:14.000000', NULL, 1),
(682123, 70683, 19780, '<td valign="top">a great action shot, catching the ball at just that moment. I don''t care much for the border though and I wish I could see the batter''s face a bit better.</td>', 'a great action shot, catching the ball at just that moment. I don''t care much for the border though and I wish I could see the batter''s face a bit better.', '2004-04-23 01:17:25.000000', NULL, 1),
(682128, 71234, 19780, '<td valign="top">A wonderful image of isolation. It''s well framed and the color and balance is compelling.</td>', 'A wonderful image of isolation. It''s well framed and the color and balance is compelling.', '2004-04-23 01:21:05.000000', NULL, 1),
(682133, 70998, 14671, '<td valign="top">I don''t really understand what the shot is supposed to be about.  Its a nice picture with great DOF but not quite sure it fits the challenge considering that I don''t know what the object is.</td>', 'I don''t really understand what the shot is supposed to be about.  Its a nice picture with great DOF but not quite sure it fits the challenge considering that I don''t know what the object is.', '2004-04-23 01:26:40.000000', NULL, 1),
