(682174, 71044, 4767, '<td valign="top">excellent concept - the hand is a little hot though...</td>', 'excellent concept - the hand is a little hot though...', '2004-04-23 02:12:54.000000', NULL, 1),
(682175, 71197, 9668, '<td valign="top">Cute shot. Although I have seen cats sleep in sinks before I don''t think I''ve seen one sleeping in a wet sink (indicated by the water drops around the inside edge). I found it mildly humorous that in you title "in Sink" could also be "N''Sync." I think the water facet detracts from the focus of this because it is to bright and sparkly. I think that this photo does fit the challenge but the general population of DPChallenge do not really care to much for cat pictures. I have a siamese cat as well that has been the subject of a few of my photos on DPChalleng. I think that overall it is an interesting photo and a different view of serendipity.</td>', 'Cute shot. Although I have seen cats sleep in sinks before I don''t think I''ve seen one sleeping in a wet sink (indicated by the water drops around the inside edge). I found it mildly humorous that in you title "in Sink" could also be "N''Sync." I think the water facet detracts from the focus of this because it is to bright and sparkly. I think that this photo does fit the challenge but the general population of DPChallenge do not really care to much for cat pictures. I have a siamese cat as well that has been the subject of a few of my photos on DPChalleng. I think that overall it is an interesting photo and a different view of serendipity.', '2004-04-23 02:14:03.000000', NULL, 1),
(682178, 71225, 4767, '<td valign="top">Don''t know how serrendipitous that discovery would be...</td>', 'Don''t know how serrendipitous that discovery would be...', '2004-04-23 02:17:16.000000', NULL, 1),
(682179, 70717, 9668, '<td valign="top">This image conveys serendipity well through the story it tells. Nice setup.</td>', 'This image conveys serendipity well through the story it tells. Nice setup.', '2004-04-23 02:17:19.000000', NULL, 1),
