(683007, 70897, 17580, '<td valign="top">Great picture, just great</td>', 'Great picture, just great', '2004-04-23 21:23:59.000000', NULL, 1),
(683009, 70635, 19608, '<td valign="top">Beautiful butterfly.  His/her color goes so well with the pink blossoms.  Too bad the background behind the butterfly is so bight; it would have gotten at least two more points if the background was very dark or even black.</td>', 'Beautiful butterfly.  His/her color goes so well with the pink blossoms.  Too bad the background behind the butterfly is so bight; it would have gotten at least two more points if the background was very dark or even black.', '2004-04-23 21:24:59.000000', NULL, 1),
