(683054, 70259, 19608, '<td valign="top">Nice seeing considering the location.  Print seems a bit muddy - without any really white whites and black blacks.  Composition is nice but doesn''t need all that sky.</td>', 'Nice seeing considering the location.  Print seems a bit muddy - without any really white whites and black blacks.  Composition is nice but doesn''t need all that sky.', '2004-04-23 22:00:49.000000', NULL, 1),
(683056, 71185, 19608, '<td valign="top">Nice lighting, nice expression.  The bottom left corner (out of focus finger and white circular shape) detracts a bit.</td>', 'Nice lighting, nice expression.  The bottom left corner (out of focus finger and white circular shape) detracts a bit.', '2004-04-23 22:02:55.000000', NULL, 1),
(683059, 71276, 19608, '<td valign="top">Great catch and awesome selection of colors.  Could have been even stronger if you have moved or zoomed in more to eliminate a lot of the white in the upper right and the wallpaper pattern in the upper left.</td>', 'Great catch and awesome selection of colors.  Could have been even stronger if you have moved or zoomed in more to eliminate a lot of the white in the upper right and the wallpaper pattern in the upper left.', '2004-04-23 22:05:26.000000', NULL, 1),
(683060, 70844, 19608, '<td valign="top">Nice feel to this image.  Relaxing.  Perhaps a bit on the contrasty side.</td>', 'Nice feel to this image.  Relaxing.  Perhaps a bit on the contrasty side.', '2004-04-23 22:06:24.000000', NULL, 1),
