(684172, 71342, 20012, '<td valign="top">this is a great idea, and well done! i love the colors in this picture, and also the fact that it''s abstract yet you don''t get completely lost.</td>', 'this is a great idea, and well done! i love the colors in this picture, and also the fact that it''s abstract yet you don''t get completely lost.', '2004-04-25 07:51:15.000000', NULL, 1),
(684174, 70816, 20012, '<td valign="top">A nice image, with a fitting title. But serendipity? I don''t get it ...</td>', 'A nice image, with a fitting title. But serendipity? I don''t get it ...', '2004-04-25 07:59:47.000000', NULL, 1),
(684176, 70535, 16241, '<td valign="top">beautiful, clear shot</td>', 'beautiful, clear shot', '2004-04-25 08:03:42.000000', NULL, 1),
