(684178, 71308, 16241, '<td valign="top">vic falls?</td>', 'vic falls?', '2004-04-25 08:05:50.000000', NULL, 1),
(684183, 71328, 20012, '<td valign="top">That''s really lucky! The pearl even comes with a hole in it for instant use ;) But this is luck, not serendipity ... there''s a very fine line between them, but it''s there.<br/><br/><i>Message edited by author 2004-04-30 09:09:46.</i></td>', 'That''s really lucky! The pearl even comes with a hole in it for instant use ;) But this is luck, not serendipity ... there''s a very fine line between them, but it''s there.', '2004-04-25 08:10:12.000000', '2004-04-30 10:09:46.000000', 1),
(684188, 70507, 20012, '<td valign="top">While this is not a great photograph (ok, it''s not that bad ...), i think it best fits the theme of this challenge. I am a bit concerned with so many people associating money or jewels with serendipity ... something much more mundane but still surprising and charming (as in this case) is much closer to its meaning, in my opinion.</td>', 'While this is not a great photograph (ok, it''s not that bad ...), i think it best fits the theme of this challenge. I am a bit concerned with so many people associating money or jewels with serendipity ... something much more mundane but still surprising and charming (as in this case) is much closer to its meaning, in my opinion.', '2004-04-25 08:12:45.000000', NULL, 1),
(684218, 70844, 16970, '<td valign="top">Let me guess you were visiting somenone and they were going on a picnic...  I agree that is a delightful suprise.  The pic captures that too.  I really like this one.  Well done.</td>', 'Let me guess you were visiting somenone and they were going on a picnic...  I agree that is a delightful suprise.  The pic captures that too.  I really like this one.  Well done.', '2004-04-25 09:12:11.000000', NULL, 1),
(684219, 70567, 15976, '<td valign="top">A great idea for a picture...although the model is too heavy to make the picture interesting.</td>', 'A great idea for a picture...although the model is too heavy to make the picture interesting.', '2004-04-25 09:15:17.000000', NULL, 1),
(684264, 71218, 16982, '<td valign="top">For a second there I thought this was an entry for the silhouettes challenge.  It would score equally brilliantly in both.</td>', 'For a second there I thought this was an entry for the silhouettes challenge.  It would score equally brilliantly in both.', '2004-04-25 10:50:52.000000', NULL, 1),
(684273, 71193, 17505, '<td valign="top">Cute. Sharp and a nice angle for both the concrete lines and the little guy''s pose. Very good. I especially like the detail on his toes. Sharp little claws!</td>', 'Cute. Sharp and a nice angle for both the concrete lines and the little guy''s pose. Very good. I especially like the detail on his toes. Sharp little claws!', '2004-04-25 11:11:02.000000', NULL, 1),
(684278, 70438, 17505, '<td valign="top">Excellent capture of a very difficult topic. Perhaps a little too much orange, I''d like the sepia to be a little more muted. Good job.</td>', 'Excellent capture of a very difficult topic. Perhaps a little too much orange, I''d like the sepia to be a little more muted. Good job.', '2004-04-25 11:14:19.000000', NULL, 1),
(684286, 71284, 16982, '<td valign="top">Excellent shot.  Really captures the challenge well.</td>', 'Excellent shot.  Really captures the challenge well.', '2004-04-25 11:22:26.000000', NULL, 1),
(684292, 70815, 16982, '<td valign="top">This is one of the best examples of serendipity I''ve seen so far.</td>', 'This is one of the best examples of serendipity I''ve seen so far.', '2004-04-25 11:33:28.000000', NULL, 1),
(684297, 70683, 16982, '<td valign="top">This is a good shot, but it does not fit the challenge very well.  The timing is very good.</td>', 'This is a good shot, but it does not fit the challenge very well.  The timing is very good.', '2004-04-25 11:44:44.000000', NULL, 1),
