(684350, 70259, 14578, '<td valign="top">Crop to obtain a panoramic image adds punch. The vast featureless sky dilutes the impact.</td>', 'Crop to obtain a panoramic image adds punch. The vast featureless sky dilutes the impact.', '2004-04-25 13:09:56.000000', NULL, 1),
