(686221, 70769, 20766, '<td valign="top">A really beautiful sunset, caught perfectly with the sun behind the clouds, off center, leaving room for the blue sky to the upper left.</td>', 'A really beautiful sunset, caught perfectly with the sun behind the clouds, off center, leaving room for the blue sky to the upper left.', '2004-04-26 17:17:49.000000', NULL, 1),
(686222, 70837, 20766, '<td valign="top">I''m not too sure what''s exactly going on here, but i do enjoy it.</td>', 'I''m not too sure what''s exactly going on here, but i do enjoy it.', '2004-04-26 17:18:32.000000', NULL, 1),
