(688524, 70722, 18552, '<td valign="top">Congratulations on your ribbon! I hope it inspires you towards many more wonderful pictures.</td>', 'Congratulations on your ribbon! I hope it inspires you towards many more wonderful pictures.', '2004-04-28 03:47:13.000000', NULL, 0),
(688544, 71305, 9168, '<td valign="top">Who are the 5 idiots that gave this a one?  Come on, this was one of the best ones here.</td>', 'Who are the 5 idiots that gave this a one?  Come on, this was one of the best ones here.', '2004-04-28 03:57:50.000000', NULL, 0),
(688546, 70897, 13035, '<td valign="top"><i><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by stdavidson:</b></div><hr/><i> Nice capture, good DOF and good quality. The digital halo on the rear end of the insect is its only fault. </i></td></tr></table></i> <br/>     Great comment st, I completely missed that noise.<br/> <br/>Congratulations gw on a well desrved ribbon.  A wonderful shot.<br/><br/><i>Message edited by author 2004-04-28 02:59:28.</i></td>', 'Originally posted by stdavidson: Nice capture, good DOF and good quality. The digital halo on the rear end of the insect is its only fault.       Great comment st, I completely missed that noise. Congratulations gw on a well desrved ribbon.  A wonderful shot.', '2004-04-28 03:58:03.000000', '2004-04-28 03:59:28.000000', 0),
(688552, 71293, 13035, '<td valign="top">I put this shot side by side with the blue ribbon and spent a while deciding which was the best.  From me, you got the 10, the blue ribbon got the 9.  Sorry that it didn''t work out in our favor.  This shot goes to my favorites.</td>', 'I put this shot side by side with the blue ribbon and spent a while deciding which was the best.  From me, you got the 10, the blue ribbon got the 9.  Sorry that it didn''t work out in our favor.  This shot goes to my favorites.', '2004-04-28 04:09:45.000000', NULL, 0),
(688559, 71305, 10170, '<td valign="top">I am guessing the 5 idiots are people who have decided it is faked and rather than request a DQ (if this was before it was verified) decided to just give it a 1 as they "knew" it was faked anyway, so why bother.<br/> <br/>The word "idiots" seems quite justified.<br/> <br/>Maybe that''s why the hand is giving them the sign it is ;)<br/><br/><i>Message edited by author 2004-04-28 03:18:34.</i></td>', 'I am guessing the 5 idiots are people who have decided it is faked and rather than request a DQ (if this was before it was verified) decided to just give it a 1 as they "knew" it was faked anyway, so why bother. The word "idiots" seems quite justified. Maybe that''s why the hand is giving them the sign it is ;)', '2004-04-28 04:17:08.000000', '2004-04-28 04:18:34.000000', 0),
(688564, 71196, 13035, '<td valign="top">Thanks to all for you comments !!!<br/><br/><i>Message edited by author 2004-04-28 03:29:47.</i></td>', 'Thanks to all for you comments !!!', '2004-04-28 04:29:32.000000', '2004-04-28 04:29:47.000000', 0),
(688566, 71305, 20064, '<td valign="top">I voted high, I realy like this picture.. but double exposure on a Sony DSC-F717 hmmmm I dont think so... perhaps you made a mistake when entering, I notice your second camera is a Nikon Coolpix 4500 which has the double exposure feature (Multiple Exposure).</td>', 'I voted high, I realy like this picture.. but double exposure on a Sony DSC-F717 hmmmm I dont think so... perhaps you made a mistake when entering, I notice your second camera is a Nikon Coolpix 4500 which has the double exposure feature (Multiple Exposure).', '2004-04-28 04:58:24.000000', NULL, 0);
